+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+pragma ComponentBehavior: Bound
+
+import QtQuick
+import QtQuick.Templates as T // For StackView
+import QtQuick.Layouts
+import org.kde.plasma.components as PlasmaComponents3
+import org.kde.plasma.extras as PlasmaExtras
+import org.kde.kirigami as Kirigami
+import org.kde.plasma.private.clipboard as Private
+
+ColumnLayout {
+    id: namePage
+    spacing: 0
+
+    required property PlasmaExtras.Representation dialogItem
+    required property Private.HistoryModel historyModel
+    required property string uuid
+    required property string name
+
+    property Item header: null
+
+    Keys.onEscapePressed: T.StackView.view.popCurrentItem()
+
+    function saveAndExit() {
+        historyModel.setName(uuid, nameField.text);
+        T.StackView.view.popCurrentItem();
+    }
+
+    T.StackView.onStatusChanged: {
+        if (namePage.T.StackView.status === T.StackView.Active) {
+            nameField.forceActiveFocus(Qt.ActiveWindowFocusReason);
+            nameField.selectAll();
+        }
+    }
+
+    PlasmaComponents3.TextField {
+        id: nameField
+        Layout.fillWidth: true
+        Layout.margins: Kirigami.Units.smallSpacing * 2
+        text: namePage.name
+        placeholderText: i18ndc("klipper", "@info:placeholder", "Name to find this item when searching")
+
+        Accessible.name: i18ndc("klipper", "@label:textbox", "Name")
+        KeyNavigation.up: namePage.dialogItem.KeyNavigation.up
+        KeyNavigation.down: saveButton
+        Keys.onEnterPressed: event => Keys.returnPressed(event)
+        Keys.onReturnPressed: namePage.saveAndExit()
+    }
+
+    Item {
+        Layout.fillHeight: true
+    }
+
+    RowLayout {
+        Layout.alignment: Qt.AlignRight
+        Layout.margins: Kirigami.Units.smallSpacing * 2
+        PlasmaComponents3.Button {
+            id: saveButton
+            text: i18ndc("klipper", "@action:button", "Save")
+            icon.name: "document-save"
+            KeyNavigation.up: nameField
+            KeyNavigation.right: cancelButton
+            onClicked: namePage.saveAndExit()
+        }
+        PlasmaComponents3.Button {
+            id: cancelButton
+            text: i18ndc("klipper", "@action:button", "Cancel")
+            icon.name: "dialog-cancel"
+            KeyNavigation.up: nameField
+            onClicked: namePage.T.StackView.view.popCurrentItem()
+        }
+    }
+}
