@@ -873,7 +894,11 @@ bool HistoryModel::loadHistory()
     query.exec(u"PRAGMA journal_mode=WAL"_s);
     // The main table only stores text data
     query.exec(
-        u"CREATE TABLE IF NOT EXISTS main (uuid char(40) PRIMARY KEY, added_time REAL NOT NULL CHECK (added_time > 0), last_used_time REAL CHECK (last_used_time > 0), mimetypes TEXT NOT NULL, text NTEXT, starred BOOLEAN)"_s);
+        u"CREATE TABLE IF NOT EXISTS main (uuid char(40) PRIMARY KEY, added_time REAL NOT NULL CHECK (added_time > 0), last_used_time REAL CHECK (last_used_time > 0), mimetypes TEXT NOT NULL, text NTEXT, starred BOOLEAN, name TEXT)"_s);
+    // Databases created before items could be named lack the name column
+    if (!query.exec(u"SELECT name FROM main LIMIT 0"_s)) {
+        query.exec(u"ALTER TABLE main ADD COLUMN name TEXT"_s);
+    }
     // The aux table stores data index
     query.exec(u"CREATE TABLE IF NOT EXISTS aux (uuid char(40) NOT NULL, mimetype TEXT NOT NULL, data_uuid char(40) NOT NULL, PRIMARY KEY (uuid, mimetype))"_s);
     // Save the latest version number
@@ -1039,6 +1064,7 @@ QHash<int, QByteArray> HistoryModel::roleNames() const
     hash.insert(TypeIntRole, QByteArrayLiteral("type"));
     hash.insert(StarredRole, QByteArrayLiteral("starred"));
     hash.insert(HasActionRole, QByteArrayLiteral("hasAction"));
+    hash.insert(NameRole, QByteArrayLiteral("name"));
     return hash;
 }

@@ -1117,6 +1143,17 @@ bool HistoryModel::isItemStarred(const QString &uuid) const
     return false;
 }

+QString HistoryModel::itemName(const QString &uuid) const
+{
+    QSqlQuery query(m_db);
+    query.prepare(u"SELECT name FROM main WHERE uuid = ?"_s);
+    query.addBindValue(uuid);
+    if (query.exec() && query.isSelect() && query.next()) {
+        return query.value(0).toString();
+    }
+    return {};
+}
